#!/usr/bin/env python3
import json
from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs

class Handler(BaseHTTPRequestHandler):
    def log_message(self, fmt, *args):
        pass

    def _send_json(self, obj, status=200):
        data = json.dumps(obj).encode('utf-8')
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        parsed = urlparse(self.path)
        if parsed.path != '/enrich':
            return self._send_json({'error': 'not found'}, 404)
        qs = parse_qs(parsed.query)
        rid = int(qs['record_id'][0])
        self._send_json({'record_id': rid, 'enriched': True})

    def do_POST(self):
        if urlparse(self.path).path != '/batch_enrich':
            return self._send_json({'error': 'not found'}, 404)
        length = int(self.headers.get('Content-Length', '0'))
        body = json.loads(self.rfile.read(length).decode('utf-8'))
        ids = body.get('record_ids', [])
        if len(ids) > 100:
            return self._send_json({'error': 'too many'}, 400)
        self._send_json({'results': [{'record_id': rid, 'enriched': True} for rid in ids]})

ThreadingHTTPServer(('127.0.0.1', 8080), Handler).serve_forever()
